from openpyxl import load_workbook

# Load the workbook
wb = load_workbook("input.xlsx")

# Access the sheets
imported_data = wb["Imported Data"]
summary_limits = wb["Summary Limits"]

# Clear the summary_limits sheet
summary_limits.clear()

# Find the header row in 'Imported Data'
header_row = None
for row in imported_data.iter_rows(min_row=1, max_row=1):
    for cell in row:
        if cell.value == "Name":
            header_row = row
            break
    if header_row:
        break

# Copy the header row to 'Summary Limits'
for i, cell in enumerate(header_row, start=1):
    summary_limits.cell(row=1, column=i, value=cell.value)

# Find rows in 'Imported Data' where the cell in column A starts with '**'
data_rows = []
for row in imported_data.iter_rows(min_row=2):
    a_cell = row[0]
    if a_cell.value and str(a_cell.value).startswith("**"):
        # Find the last non-empty cell in the row
        last_cell = None
        for cell in row:
            if cell.value:
                last_cell = cell
        if last_cell:
            data_rows.append(row[0].row)

# Copy the identified rows to 'Summary Limits'
for idx, row_num in enumerate(data_rows, start=2):
    for i, cell in enumerate(imported_data[row_num], start=1):
        summary_limits.cell(row=idx, column=i, value=cell.value)

# Save the workbook
wb.save("output.xlsx")
